'use strict';
document.getElementById('previewForm').onsubmit=async e=>{e.preventDefault();const value=id=>document.getElementById(id).value.trim(),number=id=>value(id)===''?null:Number(value(id)),button=document.getElementById('demoDownload'),status=document.getElementById('demoStatus');button.disabled=true;try{const blob=await CCAR_DOCUMENTS.build({make:value('demoMake'),model:value('demoModel'),year:value('demoYear'),km:number('demoKm'),price:number('demoPrice'),transmission:value('demoTransmission'),fuel:value('demoFuel')},{plate:value('demoPlate'),chassis:value('demoChassis'),renavam:value('demoRenavam'),color:value('demoColor')},{legal_name:value('demoName'),cnpj:value('demoCnpj'),address:value('demoAddress'),representative:value('demoRep'),representative_role:value('demoRole')},value('demoType')); CCAR_DOCUMENTS.download(blob,'C-CAR-Ficha-teste.docx');status.textContent='Arquivo gerado. Os dados desta demonstração não foram salvos.';}catch(e){status.textContent=e.message;}finally{button.disabled=false;}};
